from pathlib import Path
import json, hashlib, html, os, datetime
from urllib.parse import quote

ROOT=Path(__file__).resolve().parent
OUT=ROOT.parent
ROOT.mkdir(exist_ok=True)
def esc(x):return html.escape(str(x),quote=True)
def href(p):return quote(os.path.relpath(p,ROOT).replace('\\','/'),safe='/')
def link(p,text,cls=''):return f'<a class="{cls}" href="{href(p)}" target="_blank" rel="noopener">{esc(text)} <span aria-hidden="true">↗</span></a>'
native=OUT/'WPE_Core2_Native_Integration_R1_20261030'
academic=OUT/'WPE_Core2_Academic_Review_R1_20261031'
prep=OUT/'WPE_Source_Core1A_Completion_R2_20261030'
program=prep/'skill/source-to-core1a/examples/wpe-source-program'
source=OUT/'WPE_Question_Bank_and_Book_2026-10-30'
refs=[]
inventories=[]
for group,d in [('Question bank',source/'01_Question_Bank'),('Book and syllabus',source/'02_Book_and_Syllabus')]:
 rows=[]
 for f in sorted(d.rglob('*')):
  if not f.is_file():continue
  role='Source/reference file'
  if '_rejected-' in str(f):role='Rejected historical intake — not current'
  elif f.suffix.lower()=='.jpg':role='Original book scan'
  elif f.suffix.lower()=='.svg':role='Generated figure — correspondence unverified'
  elif f.suffix.lower()=='.py':role='Generator source — not executed here'
  elif f.suffix.lower()=='.pdf':role='Saved paper/key artifact — matching status is separate'
  elif 'Ontology' in str(f) or 'ontology' in f.name:role='Reference ontology — not a qualified warrant'
  rows.append(f'<li data-source-item data-group="{esc(group)}"><div>{link(f,f.name)}</div><small>{esc(f.relative_to(d).parent.as_posix())} · {f.stat().st_size:,} bytes</small><span class="file-role">{esc(role)}</span></li>')
  refs.append({'group':group,'path':str(f),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'role':role})
 inventories.append(f'<details class="inventory"><summary>{esc(group)} · {len(rows)} physical files</summary><ul class="files">'+''.join(rows)+'</ul></details>')
nodes=[]
for n in range(1,11):
 q=program/f'handoffs/WPE-N{n:02}.json';j=json.loads(q.read_text(encoding='utf-8-sig'))
 nodes.append(f'<li>{link(q.with_suffix(".html"),j["id"]+" · "+j["title"])}<span class="tag">Preparation · pending qualification</span></li>')

