#fff0ce;color:#795200}.tag.green{background:#dff1e8;color:#165b3e}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric{padding:18px;background:#fff;border:1px solid #d7e1ea;border-radius:11px}.metric strong{display:block;font-size:30px;line-height:1.1;color:#184b67}.metric span{font-size:13px;display:block;margin-top:8px}.callout{background:#fff5df;border-left:4px solid #c78c24;padding:15px 18px;margin:16px 0;border-radius:5px}.note{color:#576d7f;font-size:13px}.primary{display:inline-block;background:#075c89;color:#fff;padding:11px 16px;border-radius:7px;text-decoration:none;font-weight:650;margin:5px 8px 5px 0}.primary:hover{background:#03436a;color:#fff}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px 10px;text-align:left;vertical-align:top;border-bottom:1px solid #dce4ea}th{background:#f0f5f9}.gate{padding:15px 20px;border:1px dashed #b0802c;color:#674d20;background:#fffaef;border-radius:9px;margin:17px 0}.nodes{list-style:none;padding:0;columns:2;column-gap:24px}.nodes li{break-inside:avoid;margin:0 0 13px;padding:12px;border:1px solid #dce4eb;border-radius:8px}.nodes .tag{display:block;width:fit-content}.inventory{border:1px solid #d7e0e9;border-radius:8px;padding:15px;margin:12px 0}.inventory summary{cursor:pointer;font-weight:650}.files{padding:0;list-style:none}.files li{padding:12px 0;border-bottom:1px solid #e2e8ee;overflow-wrap:anywhere}.files small{display:block;color:#62768b;font-size:12px}.file-role{display:block;color:#536c81;font-size:12px}.search{width:100%;padding:12px;border:1px solid #9fb2c4;border-radius:7px;font:inherit;margin:9px 0}.scans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.scans a{padding:12px;border:1px solid #d7e0e8;border-radius:8px;text-align:center}footer{max-width:1208px;margin:auto;padding:0 24px 35px;color:#607487;font-size:13px}code{overflow-wrap:anywhere}.skip{position:absolute;left:-9999px}.skip:focus{left:15px;top:10px;background:#fff;padding:10px;z-index:10}[hidden]{display:none!important}@media(max-width:700px){header{padding:30px 18px}nav{padding:11px 18px;gap:8px 15px}main{padding:15px}.panel{padding:20px}.grid{grid-template-columns:1fr}.steps{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:1fr 1fr}.nodes{columns:1}.scans{grid-template-columns:1fr 1fr}th,td{padding:9px 7px}h2{font-size:22px}}@media print{nav{position:static}.panel{break-inside:avoid}.steps{grid-template-columns:repeat(5,1fr)}a{color:#203146}}'''
ops=[('RETRIEVE',0,3),('EXPLAIN',0,3),('APPLY',2,1),('MODEL',2,1),('REPRESENT',3,0),('SYNTHESIZE',3,0),('JUSTIFY',0,3)]
matrix=''.join(f'<tr><th>{op}</th><td>{count} unreviewed / 0 admitted</td><td>0 unreviewed / 0 admitted</td><td>{gap}</td></tr>' for op,count,gap in ops)
